CREATE TYPE "EnquiryStatus" AS ENUM ('NEW','CONTACTED','FOLLOW_UP','INTERESTED','NOT_INTERESTED','CONVERTED','CLOSED','ARCHIVED');CREATE TYPE "EnquiryPriority" AS ENUM ('LOW','MEDIUM','HIGH','URGENT');
CREATE TABLE "Enquiry" ("id" TEXT NOT NULL,"enquiryNumber" TEXT NOT NULL,"studentName" TEXT NOT NULL,"parentName" TEXT,"mobile" TEXT NOT NULL,"alternateMobile" TEXT,"email" TEXT,"address" TEXT,"branchId" TEXT NOT NULL,"courseId" TEXT,"className" TEXT,"source" TEXT NOT NULL,"counsellorId" TEXT,"nextFollowUpAt" TIMESTAMP(3),"status" "EnquiryStatus" NOT NULL DEFAULT 'NEW',"priority" "EnquiryPriority" NOT NULL DEFAULT 'MEDIUM',"remarks" TEXT,"convertedStudentId" TEXT,"convertedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Enquiry_pkey" PRIMARY KEY ("id"));CREATE TABLE "EnquiryFollowUp" ("id" TEXT NOT NULL,"enquiryId" TEXT NOT NULL,"contactedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"outcome" TEXT NOT NULL,"notes" TEXT,"nextFollowUpAt" TIMESTAMP(3),"status" "EnquiryStatus","createdById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EnquiryFollowUp_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Enquiry" ADD CONSTRAINT "Enquiry_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Enquiry" ADD CONSTRAINT "Enquiry_courseId_fkey" FOREIGN KEY ("courseId") REFERENCES "Course"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "Enquiry" ADD CONSTRAINT "Enquiry_counsellorId_fkey" FOREIGN KEY ("counsellorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "Enquiry" ADD CONSTRAINT "Enquiry_convertedStudentId_fkey" FOREIGN KEY ("convertedStudentId") REFERENCES "StudentProfile"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "EnquiryFollowUp" ADD CONSTRAINT "EnquiryFollowUp_enquiryId_fkey" FOREIGN KEY ("enquiryId") REFERENCES "Enquiry"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "EnquiryFollowUp" ADD CONSTRAINT "EnquiryFollowUp_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE UNIQUE INDEX "Enquiry_enquiryNumber_key" ON "Enquiry"("enquiryNumber");CREATE UNIQUE INDEX "Enquiry_convertedStudentId_key" ON "Enquiry"("convertedStudentId");CREATE INDEX "Enquiry_branchId_idx" ON "Enquiry"("branchId");CREATE INDEX "Enquiry_courseId_idx" ON "Enquiry"("courseId");CREATE INDEX "Enquiry_counsellorId_idx" ON "Enquiry"("counsellorId");CREATE INDEX "Enquiry_status_idx" ON "Enquiry"("status");CREATE INDEX "Enquiry_nextFollowUpAt_idx" ON "Enquiry"("nextFollowUpAt");CREATE INDEX "Enquiry_mobile_idx" ON "Enquiry"("mobile");CREATE INDEX "Enquiry_email_idx" ON "Enquiry"("email");CREATE INDEX "EnquiryFollowUp_enquiryId_contactedAt_idx" ON "EnquiryFollowUp"("enquiryId","contactedAt");
